"""Hours a candle lasts at a steady burn rate."""

def burn_hours(length_mm, mm_per_hour):
    if length_mm <= 0 or mm_per_hour <= 0:
        return 0
    return length_mm // mm_per_hour

if __name__ == "__main__":
    burn_hours(80, 10)

"""Seconds per pool lap. The drill card is not used by the timer."""

def lap_seconds(laps, elapsed):
    if laps < 1 or elapsed < 0:
        return 0
    return elapsed // laps

def drill_card(title, laps):
    return f"{title} x{laps}"

if __name__ == "__main__":
    lap_seconds(8, 480)

"""Rectangular aquarium volume in whole US gallons."""

HEATER_WATTS = 100

def tank_gallons(length_in, width_in, height_in):
    if length_in < 0 or width_in < 0 or height_in < 0:
        return 0
    cubic = length_in * width_in * height_in
    return cubic // 231

if __name__ == "__main__":
    tank_gallons(24, 12, 16)

"""Call time printed after the schedule change."""

call = "noon"
call = "evening"

def call_sheet(room):
    if not room:
        return call
    return f"{room} at {call}"

if __name__ == "__main__":
    call_sheet("hall")

"""Ink name for a print job."""

PALETTE_NAME = "sea-glass"

def ink_name(kind):
    if kind == "cover":
        return "navy"
    if kind == "text":
        return "black"
    return "paper"

if __name__ == "__main__":
    ink_name("text")

"""Bowling lane card after the shift changes."""

bowler = "early"
bowler = "late"

def lane_card(number):
    if number < 1:
        return f"{bowler} lane unset"
    return f"{bowler} lane {number}"

if __name__ == "__main__":
    lane_card(3)

"""Positions of named items on a shelf."""

ORPHAN_CAP = 12

def keeper_index(names):
    found = []
    for pos, name in enumerate(names):
        if name:
            found.append(pos)
    return found

def orphan_scan(names):
    skipped = []
    for pos, name in enumerate(names):
        if not name:
            skipped.append(pos)
    return skipped

if __name__ == "__main__":
    keeper_index(["a", "", "b"])

"""Desk badge after the slot change. The checksum helper stays unused."""

slot = "west"
slot = "east"

def desk_badge(name):
    cleaned = name.strip() or "guest"
    return f"{cleaned}:{slot}"

def spare_checksum(payload):
    total = 0
    for byte in payload.encode("utf-8"):
        total = (total + byte) % 997
    return total

if __name__ == "__main__":
    desk_badge("ada")
